public void drawPie(Graphics2D g2, Rectangle2D originalPlotArea) {
    // Setup plot area and other attributes
    Rectangle2D adjustedPlotArea = new Rectangle2D.Double(
            originalPlotArea.getX(), originalPlotArea.getY(),
            originalPlotArea.getWidth(), originalPlotArea.getHeight() - depth);

    // Draw pie segments
    for (int i = 0; i < segmentCount; i++) {
        Arc2D segment = getSegment(i);
        g2.setPaint(getColorForSegment(i));
        g2.fill(segment);
        g2.setStroke(getOutlineStroke());
        g2.setPaint(getOutlineColor());
        g2.draw(segment);

        // Draw height indicator
        Point2D p1 = segment.getStartPoint();
        int[] xs = { (int) segment.getCenterX(), (int) segment.getCenterX(),
                     (int) p1.getX(), (int) p1.getX() };
        int[] ys = { (int) segment.getCenterY(), (int) segment.getCenterY() - depth,
                     (int) p1.getY() - depth, (int) p1.getY() };
        Polygon polygon = new Polygon(xs, ys, 4);
        g2.setPaint(Color.lightGray);
        g2.fill(polygon);

        // Draw outline
        drawOutline(g2, adjustedPlotArea);
    }

    // Draw labels and tooltips if needed
    drawLabels(g2, originalPlotArea);
}
```

