```java
private void drawPie(Graphics2D g2, Rectangle2D originalPlotArea, 
                      PlotRenderingInfo info, PieSectionState state) {
    // Save the current clip and composite settings
    Shape savedClip = g2.getClip();
    Composite originalComposite = g2.getComposite();

    // Calculate depth for 3D effect
    double depth = getDepth(state);

    // Draw top section of each pie segment
    List keys = dataset.getKeys();
    int categoryCount = keys.size();
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        Comparable currentKey = (Comparable) keys.get(sectionIndex);
        Arc2D upperArc = new Arc2D.Double(
            originalPlotArea.getX(), 
            originalPlotArea.getY() + depth, 
            originalPlotArea.getWidth(), 
            originalPlotArea.getHeight() - 2 * depth,
            getStartAngle(state), 
            getSweepAngle(state),
            Arc2D.PIE
        );

        // Fill and draw the top section
        Color paint = lookupSectionPaint(currentKey);
        g2.setPaint(paint);
        g2.fill(upperArc);
        g2.setStroke(lookupSectionOutlineStroke(currentKey));
        g2.setPaint(lookupSectionOutlinePaint(currentKey));
        g2.draw(upperArc);

        // Add tooltip if enabled
        if (info != null && getToolTipGenerator() != null) {
            EntityCollection entities = info.getOwner().getEntityCollection();
            String tip = getToolTipGenerator().generateToolTip(dataset, currentKey);
            String url = getURLGenerator().generateURL(dataset, currentKey, getPieIndex());
            PieSectionEntity entity = new PieSectionEntity(
                upperArc, dataset, getPieIndex(), sectionIndex, 
                currentKey, tip, url
            );
            entities.add(entity);
        }

        // Draw labels
        if (getSimpleLabels()) {
            drawSimpleLabels(g2, keys, getDepth(state), originalPlotArea, linkArea, state);
        } else {
            drawLabels(g2, keys, getDepth(state), originalPlotArea, linkArea, state);
        }
    }

    // Restore the clip and composite settings
    g2.setClip(savedClip);
    g2.setComposite(originalComposite);

    // Draw outline of the pie chart
    drawOutline(g2, originalPlotArea);
}
