            Stroke outlineStroke = lookupSectionOutlineStroke(currentKey);

            // Draw the back side
            drawSide(g2, originalPlotArea, segment, false, true);

            // Draw the front side
            drawSide(g2, originalPlotArea, segment, true, false);
        }
