```java
public static Number parseNumber(String str) throws NumberFormatException {
    int decPos = str.indexOf('.');
    int expPos = Math.max(str.indexOf('e'), str.indexOf('E')) + 1;
    String mant, dec, exp;

    if (decPos > -1) {
        if (expPos > -1) {
