    String mant = null;
    String dec = null;
    String exp = null;

    if (decPos > -1) {
        if (expPos > -1 && expPos < decPos) {
            throw new NumberFormatException(str + " is not a valid number.");
        }
        dec = str.substring(decPos + 1, expPos > -1 ? expPos : str.length());
        mant = str.substring(0, decPos);
    } else if (expPos > -1) {
        mant = str.substring(0, expPos);
    } else {
        mant = str;
    }

    char lastChar = str.charAt(str.length() - 1);
    boolean allZeros = isAllZeros(mant);

    switch (lastChar) {
        case 'l':
        case 'L':
            if (dec == null && exp == null && (str.startsWith("-") ? isDigits(str.substring(1)) : isDigits(str))) {
                try {
                    return Long.parseLong(str);
                } catch (NumberFormatException nfe) {
                    // Too big for a long
