```java
import org.apache.commons.lang3.math.NumberUtils;

public class NumberParser {

    public static Number createNumber(String str) {
        if (str == null || str.isEmpty()) {
            throw new NumberFormatException("Input string cannot be null or empty");
        }

        int expPos = str.indexOf('e') + str.indexOf('E');
        int decPos = str.indexOf('.');
        boolean isExponentPresent = expPos > -1;
        boolean hasDecimalPoint = decPos > -1;

        if (isExponentPresent && !hasDecimalPoint) {
            throw new NumberFormatException("Invalid number format: " + str);
        }

        String numericPart = str.substring(0, Math.min(expPos, decPos));
        String exponentPart = null;
        String decimalPart = null;

        if (expPos > -1) {
            exponentPart = str.substring(expPos + 1);
            if (!hasDecimalPoint && !isExponentPresent) {
                numericPart += "0";
            }
        }

        if (decPos > -1) {
            decimalPart = str.substring(decPos + 1, expPos != -1 ? expPos : str.length());
        }

        boolean allZeros = isAllZeros(numericPart) && (exponentPart == null || isAllZeros(exponentPart));

        if (!Character.isDigit(str.charAt(str.length() - 1)) && str.charAt(str.length() - 1) != '.') {
            throw new NumberFormatException("Invalid number format: " + str);
        }

        switch (str.charAt(str.length() - 1)) {
            case 'l':
            case 'L':
                if (hasDecimalPoint && !isExponentPresent) {
                    return createBigDecimal(numericPart);
                } else {
                    try {
                        return createLong(numericPart);
                    } catch (NumberFormatException nfe) {
                        return createBigInteger(numericPart);
                    }
                }
            case 'f':
            case 'F':
                if (!allZeros && !hasDecimalPoint) {
                    return createFloat(numericPart);
                }
            case 'd':
            case 'D':
                if (!allZeros && !hasDecimalPoint) {
                    return createDouble(numericPart);
                } else {
                    return createBigDecimal(numericPart + (decimalPart != null ? "." + decimalPart : ""));
                }
            default:
                throw new NumberFormatException("Invalid number format: " + str);
        }
    }

    private static boolean isAllZeros(String s) {
        for (char c : s.toCharArray()) {
            if (!Character.isDigit(c)) return false;
        }
        return true;
    }

    // Placeholder methods for createLong, createBigInteger, createFloat, createDouble, and createBigDecimal
    public static Long createLong(String str) throws NumberFormatException {
        return Long.parseLong(str);
    }

    public static BigInteger createBigInteger(String str) throws NumberFormatException {
        return new BigInteger(str);
    }

    public static Float createFloat(String str) throws NumberFormatException {
        return Float.parseFloat(str);
    }

    public static Double createDouble(String str) throws NumberFormatException {
        return Double.parseDouble(str);
    }

    public static BigDecimal createBigDecimal(String str) throws NumberFormatException {
        return new BigDecimal(str);
    }
}
```

