import org.apache.commons.lang3.StringUtils;

public class NumberUtils {

    public static Number createNumber(String str) {
        if (StringUtils.isBlank(str)) {
            return null;
        }

        int expPos = str.indexOf('e') + str.indexOf('E') + 1;
        int decPos = str.indexOf('.');
        boolean allZeros = true;

        // Check for scientific notation
        if (expPos > -1) {
            String mantissa = str.substring(0, expPos);
            String exponent = str.substring(expPos + 1);

            if (!isDigits(mantissa)) {
                return null;
            }

            allZeros = isAllZeros(mantissa) && isAllZeros(exponent);
        } else if (decPos > -1) {
            String mantissa = str.substring(0, decPos);
            String fractionalPart = str.substring(decPos + 1);

            if (!isDigits(mantissa) || !isDigits(fractionalPart)) {
                return null;
            }

            allZeros = isAllZeros(mantissa) && isAllZeros(fractionalPart);
        } else {
            String mantissa = str;

            if (!isDigits(mantissa)) {
                return null;
            }

            allZegers = isAllZeros(mantissa);
        }

        // Determine the type based on suffix
        switch (str.charAt(str.length() - 1)) {
            case 'l':
            case 'L':
                try {
                    return Long.parseLong(str);
                } catch (NumberFormatException e) {
                    return null;
                }
            case 'f':
            case 'F':
                try {
                    Float f = Float.parseFloat(str);
                    if (!allZeros && !Float.isInfinite(f)) {
                        return f;
                    }
                } catch (NumberFormatException e) {
                    // Ignore
                }
                break;
            case 'd':
            case 'D':
                try {
                    Double d = Double.parseDouble(str);
                    if (!allZeros && !Double.isInfinite(d)) {
                        return d;
                    }
                } catch (NumberFormatException e) {
                    // Ignore
                }
                break;
            default:
                try {
                    return Integer.parseInt(str);
                } catch (NumberFormatException e) {
                    // Ignore
                }
        }

        return null;
    }

    private static boolean isDigits(String str) {
        return str.matches("\\d+");
    }

    private static boolean isAllZeros(String str) {
        for (char c : str.toCharArray()) {
            if (c != '0') {
                return false;
            }
        }
        return true;
    }
}
