import org.apache.commons.lang3.math.NumberUtils;

public class NumberParser {

    public static Number createNumber(String str) {
        if (str == null || str.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        int expPos = str.indexOf('e') + str.indexOf('E');
        boolean hasExponent = expPos > -1;

        String numericPart;
        if (hasExponent) {
            numericPart = str.substring(0, expPos);
            int exponentStart = expPos + 1;
            int exponentEnd = str.length();
            if (exponentStart < exponentEnd && !Character.isDigit(str.charAt(exponentStart))) {
                throw new NumberFormatException("Invalid exponential notation: " + str);
            }
        } else {
            numericPart = str;
        }

        boolean allZeros = isAllZeros(numericPart);

        switch (str.charAt(str.length() - 1)) {
            case 'l':
            case 'L':
                if (!hasExponent && (numericPart.charAt(0) == '-' || isDigits(numericPart))) {
                    try {
                        return createLong(numericPart);
                    } catch (NumberFormatException nfe) {
                        // Too big for a long
                    }
                }
                break;
            case 'f':
            case 'F':
                try {
                    Float f = NumberUtils.createFloat(numericPart);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
