                try {
                    Double d = NumberUtils.createDouble(numericPart);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore the bad number
                }
                try {
                    return createBigDecimal(numericPart);
                } catch (NumberFormatException e) {
                    // ignore the bad number
                }
                break;
            default:
                if (!hasExponent) {
                    try {
                        return createInteger(numericPart);
                    } catch (NumberFormatException nfe) {
                        // fall through to BigInteger
                    }
                }
                try {
                    return NumberUtils.createBigInteger(numericPart);
                } catch (NumberFormatException nfe) {
                    throw new NumberFormatException("Invalid number: " + str, nfe);
                }
        }

        throw new NumberFormatException("Invalid number: " + str);
    }

    private static boolean isAllZeros(String s) {
        for (char c : s.toCharArray()) {
            if (!Character.isDigit(c)) return false;
        }
        return true;
    }

