            }
        } catch (NumberFormatException nfe) {
            // ignore the bad number
        }

        try {
            return createBigDecimal(mant + dec);
        } catch (NumberFormatException e) {
            // ignore the bad number
        }

        throw new NumberFormatException(str + " is not a valid number.");
    }

    private static boolean isDigits(String str) {
        for (char c : str.toCharArray()) {
            if (!Character.isDigit(c)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllZeros(String str) {
        for (char c : str.toCharArray()) {
            if (c != '0') {
                return false;
            }
        }
        return true;
    }

    // Dummy methods to simulate the actual implementation
    private static Number createInteger(String str) {
        return Integer.parseInt(str);
    }

    private static Number createLong(String str) {
        return Long.parseLong(str);
    }

    private static Number createBigDecimal(String str) {
        return new BigDecimal(str);
    }
}
