```java
private void draw3DPie(Graphics2D g, Rectangle2D originalPlotArea,
                       EntityCollection info, PlotRenderingInfo info2,
                       int state) {
    // Initialize variables and set up plot area
    double x = (double) originalPlotArea.getX();
    double y = (double) originalPlotArea.getY();
    double w = (double) originalPlotArea.getWidth();
    double h = (double) originalPlotArea.getHeight() - depth;

    // Set up the clip for drawing
    Rectangle2D savedClip = g.getClipBounds();
    g.setClip(originalPlotArea);

    // Draw sides at the back
    int cat = 0;
    Iterator<Arc2D> iterator = arcList.iterator();
    while (iterator.hasNext()) {
        Arc2D segment = iterator.next();
        if (segment != null) {
            Comparable key = sectionKeys.get(cat);
            Color paint = lookupSectionPaint(key, true);
            Color outlinePaint = lookupSectionOutlinePaint(key);
            Stroke outlineStroke = lookupSectionOutlineStroke(key);
            drawSide(g, originalPlotArea, segment, front, back, paint,
                     outlinePaint, outlineStroke, false, true);
        }
        cat++;
    }

    // Draw sides at the front
    cat = 0;
    iterator = arcList.iterator();
    while (iterator.hasNext()) {
        Arc2D segment = iterator.next();
        if (segment != null) {
            Comparable key = sectionKeys.get(cat);
            Color paint = lookupSectionPaint(key);
            Color outlinePaint = lookupSectionOutlinePaint(key);
            Stroke outlineStroke = lookupSectionOutlineStroke(key);
            drawSide(g, originalPlotArea, segment, front, back, paint,
                     outlinePaint, outlineStroke, true, false);
        }
        cat++;
    }

    // Draw top surface and labels
    Arc2D upperArc;
    for (int sectionIndex = 0; sectionIndex < arcList.size(); sectionIndex++) {
        upperArc = new Arc2D.Double(x, y, w, h,
                                    segment.getAngleStart(), 
                                    segment.getAngleExtent(), Arc2D.PIE);

        Comparable currentKey = sectionKeys.get(sectionIndex);
        Color paint = lookupSectionPaint(currentKey, true);
        Color outlinePaint = lookupSectionOutlinePaint(currentKey);
        Stroke outlineStroke = lookupSectionOutlineStroke(currentKey);
        g.setPaint(paint);
        g.fill(upperArc);
        g.setStroke(outlineStroke);
        g.setPaint(outlinePaint);
        g.draw(upperArc);

        // Add tooltip
        if (info != null) {
            EntityCollection entities = info.getOwner().getEntityCollection();
            if (entities != null) {
                String tip = getToolTipGenerator().generateToolTip(dataset, currentKey);
                String url = getURLGenerator().generateURL(dataset, currentKey, getPieIndex());
                PieSectionEntity entity = new PieSectionEntity(
                        upperArc, dataset, getPieIndex(), sectionIndex, 
                        currentKey, tip, url);
                entities.add(entity);
            }
        }

        // Draw labels
        List keys = dataset.getKeys();
        Rectangle2D adjustedPlotArea = new Rectangle2D.Double(x, y, w, h - depth);
        if (getSimpleLabels()) {
            drawSimpleLabels(g, adjustedPlotArea, keys, currentKey, state);
        } else {
            drawDetailedLabels(g, adjustedPlotArea, keys, currentKey, state);
        }
    }

    // Restore the clip
    g.setClip(savedClip);
}
```

