```java
public void draw3DPieSection(Graphics2D g2, Rectangle2D originalPlotArea,
                             PieDataset dataset, int pieIndex, boolean simpleLabels) {
    // Setup variables and parameters

    // Draw sides at back
    for (int cat = 0; cat < categoryCount; cat++) {
        Arc2D segment = arcList.get(cat);
        if (segment != null) {
            drawSide(g2, originalPlotArea, segment, front, back, paint, outlinePaint, outlineStroke, false, true);
        }
    }

    // Draw sides at front
    for (int cat = 0; cat < categoryCount; cat++) {
        Arc2D segment = arcList.get(cat);
        if (segment != null) {
            drawSide(g2, originalPlotArea, segment, front, back, paint, outlinePaint, outlineStroke, true, false);
        }
    }

    // Draw top section
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        Arc2D upperArc = arcList.get(sectionIndex);
        if (upperArc != null) {
            Comparable currentKey = keys.get(sectionIndex);
            g2.setPaint(paint);
            g2.fill(upperArc);
            g2.setStroke(outlineStroke);
            g2.setPaint(outlinePaint);
            g2.draw(upperArc);

            // Add tooltip
            if (info != null) {
                EntityCollection entities = info.getOwner().getEntityCollection();
                if (entities != null) {
                    String tip = getToolTipGenerator().generateToolTip(dataset, currentKey);
                    String url = getURLGenerator().generateURL(dataset, currentKey, pieIndex);
                    PieSectionEntity entity = new PieSectionEntity(upperArc, dataset, pieIndex, sectionIndex, currentKey, tip, url);
                    entities.add(entity);
                }
            }

            // Draw labels
            if (simpleLabels) {
                drawSimpleLabels(g2, keys, totalValue, adjustedPlotArea, linkArea, state);
            } else {
                drawLabels(g2, keys, totalValue, adjustedPlotArea, linkArea, state);
            }
        }
    }

    // Draw outline and restore clip
    drawOutline(g2, originalPlotArea);
}
```

