switch (tType) {
    case 0: // No eigenvalue deflated yet
        tau = dMin * 0.5;
        tType = -6; // Default type for no deflation
        break;

    case 1: // One eigenvalue just deflated, use dMin1 and dN1
        if (dMin1 == dN1 && dMin2 == dN2) {
            tau = 0.333 * dMin1;
            tType = -7; // Case 7 or 8
            double b1 = work[nn - 5] / work[nn - 7];
            double b2 = b1;
