        dec = str.substring(decPos + 1);
        mant = str.substring(0, decPos);
    } else {
        if (expPos > -1) {
            mant = str.substring(0, expPos);
        } else {
            mant = str;
        }
        dec = null;
    }

    // Attempt to parse as long first
    try {
        return Long.parseLong(mant);
    } catch (NumberFormatException e) {
        // Fall through to next type
    }

    // Attempt to parse as float or double
    if (!Character.isDigit(lastChar) && lastChar != '.') {
        String numeric = str.substring(0, str.length() - 1);
        try {
            Float f = Float.parseFloat(numeric);
            if (!(f.isInfinite() || (f.floatValue() == 0.0F))) {
                return f;
            }
        } catch (NumberFormatException e) {
            // Fall through to next type
        }

        try {
            Double d = Double.parseDouble(numeric);
            if (!(d.isInfinite() || (d.doubleValue() == 0.0D))) {
                return d;
            }
        } catch (NumberFormatException e) {
            // Fall through to next type
        }
    }

    // Default to BigDecimal
    try {
        return new BigDecimal(str);
    } catch (NumberFormatException e) {
        throw new NumberFormatException("Input string is not a valid number: " + str);
    }
}
```

This version maintains the simplicity of the revised implementation while ensuring robust error handling.

