function minimizeExits(node, exitType = 'RETURN', labelName) {
    if (matchingExitNode(node, exitType, labelName)) {
        // Remove child from its parent.
        node.getParent().removeChild(node);
        compiler.reportCodeChange();
        return;
    } else if (node.isIf()) {
        let ifBlock = node.getFirstChild().getNext();
        minimizeExits(ifBlock, exitType, labelName);
        let elseBlock = ifBlock.getNext();
        if (elseBlock != null) minimizeExits(elseBlock, exitType, labelName);
    } else if (node.isTry()) {
        let tryBlock = node.getFirstChild();
        minimizeExits(tryBlock, exitType, labelName);
        let allCatchNodes = NodeUtil.getCatchBlock(node);
        if (NodeUtil.hasCatchHandler(allCatchNodes)) {
            let catchNode = allCatchNodes.getFirstChild();
            let catchCodeBlock = catchNode.getLastChild();
            minimizeExits(catchCodeBlock, exitType, labelName);
        }
        if (NodeUtil.hasFinally(node)) {
            let finallyBlock = node.getLastChild();
            minimizeExits(finallyBlock, exitType, labelName);
        }
    } else if (node.isLabel()) {
        let labelBlock = node.getLastChild();
        minimizeExits(labelBlock, exitType, labelName);
    } 
