```java
// This method finds the minimum entry in the first row of a SimplexTableau and returns its column index
private Integer getPivotColumn(SimplexTableau tableau) {
    // Initialize minValue to 0 and minPos as null
    double minValue = 0;
    Integer minPos = null;

    // Iterate over the columns in the SimplexTableau, starting from the number of objective functions
    for(int i = tableau.getNumObjectiveFunctions(); i < tableau.getWidth() - 1; i++) {
        // If the current entry is less than minValue (compared with a small epsilon value), update minValue and minPos
        if(MathUtils.compareTo(tableau.getEntry(0, i), minValue, epsilon) < 0) {
            minValue = tableau.getEntry(0, i);
            minPos = i;
        }
    }

    // Return the column index of the minimum entry found in the first row
    return minPos;
}
