```java
public static Number createNumber(String str) {
    if (str == null || str.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    // Handle special cases like "0x" or "-0x"
    if (str.startsWith("0x") || str.startsWith("-0x")) {
        return createInteger(str);
    }

    char lastChar = str.charAt(str.length() - 1);
    String mant;
    String dec;
    String exp;
    int decPos = str.indexOf('.');
    int expPos = str.indexOf('e') + str.indexOf('E') + 1;

    if (decPos > -1) {
        if (expPos > -1 && expPos < decPos) {
            throw new NumberFormatException(str + " is not a valid number.");
        }
        dec = str.substring(decPos + 1);
        mant = str.substring(0, decPos);
    } else {
        if (expPos > -1) {
            mant = str.substring(0, expPos);
        } else {
            mant = str;
        }
        dec = null;
    }

    // Handle specific numeric types based on the last character
    switch (lastChar) {
        case 'l':
        case 'L':
            if (dec == null && exp == null && isDigits(mant.substring(1))) {
                try {
                    return createLong(mant);
                } catch (NumberFormatException nfe) {
                    // Too big for a long
                }
            }
            break;
        case 'f':
        case 'F':
            try {
                Float f = NumberUtils.createFloat(mant);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && isAllZeros(mant)))) {
                    return f;
                }
            } catch (NumberFormatException nfe) {
                // Ignore bad number
            }
            break;
        case 'd':
        case 'D':
            try {
                Double d = NumberUtils.createDouble(mant);
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && isAllZeros(mant)))) {
                    return d;
                }
            } catch (NumberFormatException nfe) {
                // Ignore bad number
            }
            break;
    }

    // Default to BigInteger or Integer based on the presence of an exponent
    if (exp != null) {
        return createBigInteger(str);
    } else {
        try {
            return createInteger(mant);
        } catch (NumberFormatException nfe) {
            // Fallback to Double if all else fails
            return NumberUtils.createDouble(mant);
        }
    }
}

private static boolean isDigits(String str) {
    for (char c : str.toCharArray()) {
        if (!Character.isDigit(c)) {
            return false;
        }
    }
    return true;
}

private static boolean isAllZeros(String str) {
    for (char c : str.toCharArray()) {
        if (c != '0') {
            return false;
        }
    }
    return true;
}
```

