 ```java
/**
 * Draws the side of a pie section.
 *
 * @param g2  the graphics device.
 * @param pieArea  the area in which the pie is drawn.
 * @param segment  the arc that defines the section.
 * @param front  the path for the front of the pie.
 * @param back  the path for the back of the pie.
 * @param paint  the paint to use for filling the section.
 * @param outlinePaint  the paint to use for outlining the section.
 * @param outlineStroke  the stroke to use for outlining the section.
 * @param drawFront  whether or not to draw the front of the section.
 * @param drawBack  whether or not to draw the back of the section.
 */
private void drawSide(Graphics2D g2, Rectangle2D pieArea, Arc2D segment,
                      GeneralPath front, GeneralPath back, Paint paint,
                      Paint outlinePaint, Stroke outlineStroke,
                      boolean drawFront, boolean drawBack) {
    double angleStart = segment.getAngleStart();
    double angleExtent = segment.getAngleExtent();
    double x1 = pieArea.getX() + pieArea.getWidth() / 2;
    double y1 = pieArea.getY() + pieArea.getHeight() / 2;
    double radius = Math.min(pieArea.getWidth(), pieArea.getHeight()) / 2;

    GeneralPath path = new GeneralPath();
    path.moveTo(x1, y1);
    path.lineTo(x1 + radius * Math.cos(Math.toRadians(angleStart)),
                y1 - radius * Math.sin(Math.toRadians(angleStart)));
    path.quadTo(x1, y1,
                 x1 + radius * Math.cos(Math.toRadians(angleStart + angleExtent / 2)),
                 y1 - radius * Math.sin(Math.toRadians(angleStart + angleExtent / 2)));
    path.lineTo(x1 + radius * Math.cos(Math.toRadians(angleStart + angleExtent)),
                y1 - radius * Math.sin(Math.toRadians(angleStart + angleExtent)));
    path.closePath();

    if (drawFront) {
        front.append(path, false);
        g2.setPaint(paint);
        g2.fill(path);
        g2.setStroke(outlineStroke);
        g2.setPaint(outlinePaint);
        g2.draw(path);
    }

    if (drawBack) {
        back.append(path, true);
        g2.setPaint(Color.gray);
        g2.fill(path);
    }
}
```

