    private void drawSide(Graphics2D g2, Rectangle2D plotArea, Arc2D arc, Color front, Color back, Paint paint, 
            Paint outlinePaint, Stroke outlineStroke, boolean fillFront, boolean fillBack) {
        GeneralPath path = new GeneralPath();
        double startAngle = Math.toRadians(arc.getAngleStart());
        double extentAngle = Math.toRadians(arc.getAngleExtent());

        // Calculate the corners of the pie section
        double x1 = plotArea.getCenterX() + arc.getWidth() / 2 * Math.cos(startAngle);
        double y1 = plotArea.getCenterY() - arc.getHeight() / 2 * Math<｜begin▁of▁sentence｜>Math.sin(startAngle);

        double x2 = plotArea.getCenterX() + arc.getWidth() / 2 * Math.cos(startAngle + extentAngle);
        double y2 = plotArea.getCenterY() - arc.getHeight() / 2 * Math.sin(startAngle + extentAngle);

        path.moveTo(x1, y1);
        path.lineTo(plotArea.getMaxX(), y1);
        path.lineTo(plotArea.getMaxX(), plotArea.getMaxY());
        path.lineTo(x2, plotArea.getMaxY());
        path.closePath();

        if (fillFront) {
            g2.setPaint(paint);
            g2.fill(path);
        } else {
            g2.setColor(front);
            g2.draw(path);
        }

        if (fillBack) {
            g2.setPaint(back);
            g2.fill(path);
        } else {
            g2.setColor(back);
            g2.draw(path);
        }

        // Draw the outline of the pie section
        if (outlineStroke != null) {
            g2.setStroke(outlineStroke);
            g2.setPaint(outlinePaint);
            g2.draw(path);
        }
    }
```
