public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            throw new NumberFormatException("\"\" is not a valid number.");
        }
        if (str.equalsIgnoreCase("NaN")) {
            return Double.valueOf(java.lang.Double.NaN);
        }
        char lastChar = str.charAt(str.length() - 1);
        String mantissa;
        String exponent = null;
        int expPos = str.indexOf('E');
        if (expPos > -1) {
            mantissa = str.substring(0, expPos);
            exponent = str.substring(expPos + 1);
        } else {
            mantissa = str;
        }
        boolean allZeros = isAllZeros(mantissa) && (exponent == null || isAllZeros(exponent));
        if ('l' == lastChar || 'L' == lastChar) {
            if (isDigits(str.substring(0, str.length() - 1))) {
                try {
                    return createLong(str.substring(0, str.length() - 1));
                } catch (NumberFormatException nfe) {
                    //Too big for a long
                }
            }
            throw new NumberFormatException(str + " is not a valid number.");
        } else if ('f' == lastChar || 'F' == lastChar) {
            try {
                Float f = createFloat(str.substring(0, str.length() - 1));
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                    return f;
                }
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } else if ('d' == lastChar || 'D' == lastChar) {
            try {
                Double d = createDouble(str.substring(0, str.length() - 1));
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                    return d;
                }
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } else if ('b' == lastChar || 'B' == lastChar) {
            try {
                return createBigInteger(str.substring(0, str.length() - 1));
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } else if ('s' == lastChar || 'S' == lastChar) {
            try {
                return createShort(str.substring(0, str.length() - 1));
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } else if ('c' == lastChar || 'C' == lastChar) {
            try {
                return createCharacter(str.substring(0, str.length() - 1));
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } else if ('i' == lastChar || 'I' == lastChar) {
            try {
                return createInteger(str.substring(0, str.length() - 1));
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } else if ('e' == lastChar || 'E' == lastChar) {
            try {
                return createFloat(str);
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        } 
        try {
            return createInteger(str);
        } catch (NumberFormatException nfe) {
            // ignore the bad number
        }
        try {
            return createLong(str);
        } catch (NumberFormatException nfe) {
            // ignore the bad number
        }
        try {
            Double d = createDouble(str);
            if (!d.isInfinite()) {
                return d;
            }
        } catch (NumberFormatException nfe) {
            // ignore the bad number
        }
        try {
            return createBigInteger(str);
        } catch (NumberFormatException nfe) {
            // ignore the bad number
        }
        throw new NumberFormatException("\"" + str + "\" is not a valid number.");
    }
