@Override
protected void drawItem(Graphics2D g2, Rectangle2D plotArea, PlotRenderingInfo info, PiePlotState state) {
    // Get the dataset and keys
    PieDataset dataset = getDataset();
    List sectionKeys = dataset.getKeys();
    int categoryCount = sectionKeys.size();

    // Calculate some values for drawing the pie
    double depth = plotArea.getWidth() / 3;
    Rectangle2D originalPlotArea = (Rectangle2D) plotArea.clone();
    plotArea.setRect(plotArea.getX(), plotArea.getY() + depth, plotArea.getWidth(), plotArea.getHeight() - depth);

    // Draw the sections at the front of the pie
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        Arc2D segment = (Arc2D) arcList.get(sectionIndex);
        if (segment == null) continue;

        Comparable key = getSectionKey(sectionIndex);
        Paint paint = lookupSectionPaint(key, true);
        Stroke stroke = lookupSectionOutlineStroke(key);
        g2.setPaint(paint);
        g2.fill(segment);
        g2.setStroke(stroke);
        g2.draw(segment);
    }

    // Draw the sections at the sides of the pie
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        Arc2D segment = (Arc2D) arcList.get(sectionIndex);
        if (segment == null) continue;

        Comparable key = getSectionKey(sectionIndex);
        Paint paint = lookupSectionPaint(key, true);
        Stroke stroke = lookupSectionOutlineStroke(key);
        drawSide(g2, pieArea, segment, front, back, paint, outlinePaint, stroke, true, false);
    }

    // Draw the sections at the top of the pie
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        Arc2D arc = (Arc2D.Double) arcList.get(sectionIndex);
        if (arc == null) continue;

        Comparable key = (Comparable) sectionKeys.get(sectionIndex);
        Paint paint = lookupSectionPaint(key, true);
        Stroke stroke = lookupSectionOutlineStroke(key);
        g2.setPaint(paint);
        g2.fill(arc);
        g2.setStroke(stroke);
        g2.draw(arc);
    }

    // Draw the labels if needed
    if (getSimpleLabels()) {
        drawSimpleLabels(g2, sectionKeys, totalValue, originalPlotArea, linkArea, state);
    } else {
        drawLabels(g2, sectionKeys, totalValue, originalPlotArea, linkArea, state);
    }

    // Draw the outline of the pie if needed
    if (getDrawBorder()) drawOutline(g2, plotArea);
}
```

