lines2 = code2.split("\n")

# Create a diff object
d = difflib.Differ()

# Get the difference between two lists of lines
differences = d.compare(lines1, lines2)

# Count how many differences there are
num_diffs = sum(1 for _ in differences if _.startswith('-') or _.startswith('+'))

# Calculate similarity as (number of different lines / total number of lines)
similarity = 1 - num_diffs / max(len(lines1), len(lines2))
