public static Number parseNumber(String str) throws NumberFormatException {
    int decPos = str.indexOf('.');
    int expPos = Math.max(str.indexOf('e'), str.indexOf('E')) + 1;
    String mant, dec, exp;

    if (decPos > -1) {
        if (expPos > -1 && expPos < decPos || expPos > str.length()) {
            throw new NumberFormatException(str + " is not a valid number.");
        }
        dec = str.substring(decPos + 1, expPos);
        mant = str.substring(0, decPos);
    } else {
        if (expPos > -1 && expPos > str.length()) {
            throw new NumberFormatException(str + " is not a valid number.");
        }
        mant = str;
        dec = null;
    }

    char lastChar = str.charAt(str.length() - 1);
    switch (lastChar) {
        case 'l':
        case 'L':
            return createLong(mant);
        case 'f':
        case 'F':
            try {
                Float f = NumberUtils.createFloat(mant);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && isAllZeros(dec)))) {
                    return f;
                }
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        case 'd':
        case 'D':
            try {
                Double d = NumberUtils.createDouble(mant);
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && isAllZeros(dec)))) {
                    return d;
                }
            } catch (NumberFormatException nfe) {
                // ignore the bad number
            }
        default:
            try {
                return createBigDecimal(mant);
            } catch (NumberFormatException e) {
                throw new NumberFormatException(str + " is not a valid number.");
            }
    }
}

private static boolean isAllZeros(String s) {
    for (char c : s.toCharArray()) {
        if (c != '0') {
            return false;
        }
    }
    return true;
}
