Here is a simple implementation of the `replaceEach` method in Java:

```java
public class StringUtils {

  /**
   * Replace all occurrences of Strings within another String.
   */
  public static String replaceEach(String text, String[] searchList, String[] replacementList) {
    return replaceEach(text, searchList, replacementList, true, 10);
  }

  /**
   * Private recursive method to handle the replacement.
   */
  private static String replaceEach(String text, String[] searchList, String[] replacementList, boolean repeat, int timeToLive) {
    if (text == null || text.isEmpty() || searchList == null || 
        searchList.length == 0 || replacementList == null || replacementList.length == 0) {
      return text;
    }

    int searchLength = searchList.length;
    int replaceLength = replacementList.length;

    if (searchLength != replaceLength) {
      throw new IllegalArgumentException("Search and Replace array lengths don't match: " + searchLength + " vs " + replaceLength);
    }

    boolean[] noMoreMatchesForReplIndex = new boolean[searchLength];

    int textIndex = -1;
    int replaceIndex = -1;
    int tempIndex = -1;

    for (int i = 0; i < searchLength; i++) {
      if (noMoreMatchesForReplIndex[i] || searchList[i] == null || searchList[i].length() == 0 || replacementList[i] == null) {
        continue;
      }
      tempIndex = text.indexOf(searchList[i]);

      if (tempIndex == -1) {
        noMoreMatchesForReplIndex[i] = true;
      } else if (textIndex == -1 || tempIndex < textIndex) {
        textIndex = tempIndex;
        replaceIndex = i;
      }
    }

    if (textIndex == -1) {
      return text;
    }

    int start = 0;

    int increase = 0;

    for (int i = 0; i < searchLength; i++) {
      int greater = replacementList[i].length() - searchList[i].length();
      if (greater > 0) {
        increase += 3 * greater; // assume 3 matches
      }
    }

    increase = Math.min(increase, text.length() / 5);

    StringBuilder buf = new StringBuilder(text.length() + increase);

    while (textIndex != -1) {

      for (int i = start; i < textIndex; i++) {
        buf.append(text.charAt(i));
      }
      buf.append(replacementList[replaceIndex]);

      start = textIndex + searchList[replaceIndex].length();

      textIndex = -1;
      replaceIndex = -1;
      tempIndex = -1;

      for (int i = 0; i < searchLength; i++) {
        if (noMoreMatchesForReplIndex[i] || searchList[i] == null || searchList[i].length() == 0 || replacementList[i] == null) {
          continue;
        }
        tempIndex = text.indexOf(searchList[i], start);

        if (tempIndex == -1) {
          noMoreMatchesForReplIndex[i] = true;
        } else if (textIndex == -1 || tempIndex < textIndex) {
          textIndex = tempIndex;
          replaceIndex = i;
        }
      }
    }

    int textLength = text.length();
    for (int i = start; i < textLength; i++) {
      buf.append(text.charAt(i));
    }

    String result = buf.toString();
    if (!repeat || timeToLive <= 0) {
      return result;
    }

    return replaceEach(result, searchList, replacementList, repeat, timeToLive - 1);
  }
}
```

