private void drawPie(Graphics2D g2, Rectangle2D originalPlotArea, PieDataset dataset, int pieIndex, EntityCollection info) {
    // Initialize necessary variables and state

    // Draw sides at the back
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        drawSide(g2, pieArea, arcList.get(sectionIndex), front, back, paint, outlinePaint, outlineStroke, false, true);
    }

    // Draw sides at the front
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        drawSide(g2, pieArea, arcList.get(sectionIndex), front, back, paint, outlinePaint, outlineStroke, true, false);
    }

    // Draw top sections
    for (int sectionIndex = 0; sectionIndex < categoryCount; sectionIndex++) {
        Arc2D upperArc = new Arc2D.Double(arcX, arcY, pieArea.getWidth(), pieArea.getHeight() - depth, arc.getAngleStart(), arc.getAngleExtent(), Arc2D.PIE);

        Comparable currentKey = (Comparable) sectionKeys.get(sectionIndex);
        paint = lookupSectionPaint(currentKey, true);
        outlinePaint = lookupSectionOutlinePaint(currentKey);
        outlineStroke = lookupSectionOutlineStroke(currentKey);

        g2.setPaint(paint);
        g2.fill(upperArc);
        g2.setStroke(outlineStroke);
        g2.setPaint(outlinePaint);
        g2.draw(upperArc);

        // Add a tooltip for the section
        if (info != null) {
            EntityCollection entities = info.getOwner().getEntityCollection();
            if (entities != null) {
                String tip = null;
                PieToolTipGenerator tipster = getToolTipGenerator();
                if (tipster != null) {
                    tip = tipster.generateToolTip(dataset, currentKey);
                }
                String url = null;
                if (getURLGenerator() != null) {
                    url = getURLGenerator().generateURL(dataset, currentKey, getPieIndex());
                }
                PieSectionEntity entity = new PieSectionEntity(upperArc, dataset, getPieIndex(), sectionIndex, currentKey, tip, url);
                entities.add(entity);
            }
        }

        // Handle labels
        List keys = dataset.getKeys();
        Rectangle2D adjustedPlotArea = new Rectangle2D.Double(originalPlotArea.getX(), originalPlotArea.getY(), originalPlotArea.getWidth(), originalPlotArea.getHeight() - depth);
        if (getSimpleLabels()) {
            drawSimpleLabels(g2, adjustedPlotArea, keys, currentKey);
        } else {
            drawDetailedLabels(g2, adjustedPlotArea, keys, currentKey);
        }
    }

    // Finalize drawing
    g2.dispose();
}

